# objects = each connected component of same color (8 marker singletons); independently translate right until collision or boundary
h,w=len(G),len(G[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if G[r][c] and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c))
   for y,x in q:
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=y+dy,x+dx
     if 0<=a<h and 0<=b<w and G[a][b]==G[r][c] and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   comps.append((G[r][c],q))
# collision-free, process right to left by right edge
out=[[0]*w for _ in range(h)]
for col,q in sorted(comps,key=lambda x:max(c for r,c in x[1]),reverse=True):
 d=0
 while all(c+d+1<w and out[r][c+d+1]==0 for r,c in q):d+=1
 for r,c in q:out[r][c+d]=col
print('\n'.join(' '.join(map(str,row)) for row in out))
